item.aggregated_output:
                d["zones"]["discard"].append(card)
            self._propose(d, action, cards)
        elif typ == "give_card":
            card = args["card"]; pending = d["pending"]
            d["players"][actor]["hand"].remove(card)
            d["players"][pending["actor"]]["hand"].append(card)
            d["current_player"], d["phase"], d["pending"] = pending["actor"], "play", None
        elif typ == "reinsert":
            d["zones"]["deck"].insert(args["position"], "exploding_kitten")
            self._advance(d)
        elif typ == "pass_nope":
            p = d["pending"]
            if p["remaining_responders"]:
                p["responder"] = p["remaining_responders"].pop(0)
            else:
                proposed, active = p["proposed"], p["nope_count"] % 2 == 0
                if active: self._resolve(d, proposed)
                else: d["phase"], d["pending"] = "play", None
        elif typ == "play_nope":
            d["players"][actor]["hand"].remove("nope"); d["zones"]["discard"].append("nope")
            p = d["pending"]; p["nope_count"] += 1
            responders = self._responders(d, actor)
            p["responder"] = responders[0]
            p["remaining_responders"] = responders[1:]
        return s

    def action_to_name(self, action):
        labels = {"draw": "Draw", "play_card": "Play", "play_pair": "Pair",
                  "play_triple": "Triple", "play_five": "Five",
                  "give_card": "Give", "reinsert": "Reinsert",
                  "play_nope": "NÃ–!", "pass_nope": "Pass NÃ–!"}
        tail = json.dumps(action.args, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        return f"{labels[action.type]} [player {action.actor}] {tail}"

    def name_to_action(self, name):
        for typ in ACTION_TYPES:
            label = self.action_to_name(Action(typ, 0)).split(" [", 1)[0]
            prefix = label + " [player "
            if name.startswith(prefix):
                rest = name[len(prefix):]
                actor_s, tail = rest.split("] ", 1)
                return Action(typ, int(actor_s), json.loads(tail))
        raise ValueError("unknown action name")

    def action_to_data(self, action):
        return {"schema": ACTION_SCHEMA, "data": {"type": action.type, "actor": action.actor,
                                                  "args": copy.deepcopy(action.args)}}

    def action_from_data(self, payload):
        self._envelope(payload, ACTION_SCHEMA)
        d = payload["data"]
        if set(d) != {"type", "actor", "args"} or d.get("type") not in ACTION_TYPES:
            raise ValueError("invalid action fields")
        if not _is_int(d["actor"]) or not isinstance(d["args"], dict):
            raise ValueError("invalid action")
        expected = {"draw": set(), "play_card": {"card", "target"}, "play_pair": {"card", "target"},
                    "play_triple": {"card", "target", "requested"}, "play_five": {"cards", "retrieve"},
                    "give_card": {"card"}, "reinsert": {"position"}, "play_nope": set(), "pass_nope": set()}
        if set(d["args"]) != expected[d["type"]]:
            raise ValueError("invalid action arguments")
        return Action(d["type"], d["actor"], copy.deepcopy(d["args"]))

    def state_to_data(self, state):
        return {"schema": STATE_SCHEMA, "data": copy.deepcopy(state.data)}

    def _envelope(self, payload, schema):
        if not isinstance(payload, dict) or set(payload) != {"schema", "data"}:
            raise ValueError("invalid envelope")
        if payload["schema"] != schema or not isinstance(payload["data"], dict):
            raise ValueError("invalid schema")

    def state_from_data(self, payload):
        self._envelope(payload, STATE_SCHEMA)
        d = payload["data"]
        required = {"configuration", "players", "zones", "current_player", "turns_owed",
                    "phase", "pending", "terminal", "winner", "turn_number", "chance"}
        if set(d) != required:
            raise ValueError("invalid state fields")
        if d.get("phase") not in PHASES or not isinstance(d.get("players"), list):
            raise ValueError("invalid state")
        # Strict JSON-domain/card validation while permitting evaluator fixture zone layouts.
        json.dumps(payload, allow_nan=False)
        if any(c not in CARDS for p in d["players"] for c in p.get("hand", []) + p.get("preview", [])):
            raise ValueError("unknown card")
        if any(c not in CARDS for z in d["zones"].values() for c in z):
            raise ValueError("unknown card")
        return GameState(copy.deepcopy(d))

    def observation_to_data(self, state, player):
        d = state.data
        if not _is_int(player) or not 0 <= player < len(d["players"]):
            raise ValueError("invalid player")
        pending = copy.deepcopy(d["pending"])
        data = {"player": player, "own_hand": list(d["players"][player]["hand"]),
                "opponent_hand_sizes": {str(p["id"]): len(p["hand"]) for p in d["players"] if p["id"] != player},
                "deck_size": len(d["zones"]["deck"]), "discard": list(d["zones"]["discard"]),
                "alive": [p["alive"] for p in d["players"]], "current_player": d["current_player"],
                "turns_owed": d["turns_owed"], "phase": d["phase"], "pending": pending,
                "preview": list(d["players"][player]["preview"]), "terminal": d["terminal"],
                "winner": d["winner"], "turn_number": d["turn_number"]}
        return {"schema": OBS_SCHEMA, "data": data}

    def render(self, state):
        d = state.data
        if d["terminal"]:
            return f"Spielende â€” player {d['winner']} wins."
        sizes = ", ".join(f"P{p['id']}:{len(p['hand'])}{'' if p['alive'] else ' (out)'}" for p in d["players"])
        return f"Turn {d['turn_number']} | {d['phase']} | player {d['current_player']} | deck {len(d['zones']['deck'])} | {sizes}"
#!/usr/bin/env python3
"""Evaluator-neutral canonical fixture reconstruction check for Exploding Kittens V2."""

from __future__ import annotations

import copy
import importlib.util
import json
from collections import Counter
from pathlib import Path

MODULE_PATH = Path(__file__).with_name("implementation.py")
PROFILE_PATH = Path(__file__).with_name("GAME_PROFILE.json")
COUNTS = {
    "exploding_kitten": 4, "defuse": 6, "attack": 4, "nope": 5, "skip": 4,
    "favor": 4, "shuffle": 4, "see_future": 5, "cat_beard": 4,
    "cat_cattermelon": 4, "cat_hairy_potato": 4, "cat_rainbow": 4, "cat_tacocat": 4,
}


def load_module():
    spec = importlib.util.spec_from_file_location("fixture_checked_implementation", MODULE_PATH)
    if spec is None or spec.loader is None:
        raise RuntimeError(f"cannot load {MODULE_PATH}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def cards(data):
    result = [card for player in data["players"] for card in player["hand"]]
    for zone in ("deck", "discard", "box"):
        result.extend(data["zones"][zone])
    pending = data.get("pending")
    if isinstance(pending, dict) and pending.get("type") == "defuse":
        result.append(pending["kitten"])
    return result


def roundtrip(game, payload, label):
    rebuilt = game.state_from_data(copy.deepcopy(payload))
    actual = game.state_to_data(rebuilt)
    assert actual == payload, f"{label} did not round-trip"
    game.current_player(rebuilt)
    game.is_terminal(rebuilt)
    game.returns(rebuilt)
    for action in game.legal_actions(rebuilt):
        encoded = game.action_to_data(action)
        assert game.action_to_data(game.action_from_data(copy.deepcopy(encoded))) == encoded
    for player in range(payload["data"]["configuration"]["players"]):
        observation = game.observation_to_data(rebuilt, player)
        assert observation["schema"] == "boardbench/exploding-kittens/observation/2"


def fixture(base, phase, pending=None):
    payload = copy.deepcopy(base)
    data = payload["data"]
    inventory = Counter(cards(data))
    for player in data["players"]:
        player["hand"] = []
        player["preview"] = []
        player["alive"] = True
    data["zones"] = {"deck": [], "discard": [], "box": sorted(inventory.elements())}
    data["current_player"] = 0
    data["turns_owed"] = 1
    data["phase"] = phase
    data["pending"] = copy.deepcopy(pending)
    data["terminal"] = phase == "terminal"
    data["winner"] = 0 if phase == "terminal" else None
    if phase == "terminal":
        data["players"][1]["alive"] = False
    return payload


def move(data, target, card):
    data["zones"]["box"].remove(card)
    target.append(card)


def main():
    module = load_module()
    profile = json.loads(PROFILE_PATH.read_text(encoding="utf-8"))
    for count in profile["player_counts"]["supported"]:
        game = module.Game(num_players=count, seed=1)
        payload = game.state_to_data(game.initial_state())
        assert payload["schema"] == profile["state_schema"]
        assert Counter(cards(payload["data"])) == Counter(COUNTS)
        roundtrip(game, payload, f"{count}-player initial")

    game = module.Game(num_players=2, seed=1)
    base = game.state_to_data(game.initial_state())
    pending_by_phase = {
        "play": None,
        "reaction": {"type": "reaction", "proposed": {"type": "play_card", "actor": 0, "args": {"card": "attack", "target": None}}, "cards": ["attack"], "nope_count": 0, "responder": 1, "remaining_responders": [1]},
        "favor_give": {"type": "favor", "actor": 0, "target": 1},
        "defuse_reinsert": {"type": "defuse", "actor": 0, "kitten": "exploding_kitten"},
        "terminal": None,
    }
    for phase, pending in pending_by_phase.items():
        payload = fixture(base, phase, pending)
        data = payload["data"]
        if phase == "reaction":
            move(data, data["zones"]["discard"], "attack")
            move(data, data["players"][1]["hand"], "nope")
        elif phase == "favor_give":
            move(data, data["players"][1]["hand"], "skip")
        elif phase == "defuse_reinsert":
            data["zones"]["box"].remove("exploding_kitten")
            move(data, data["zones"]["deck"], "attack")
            move(data, data["zones"]["discard"], "defuse")
        assert Counter(cards(data)) == Counter(COUNTS)
        roundtrip(game, payload, phase)
    print("profile-fixture-self-check OK")


if __name__ == "__main__":
    main()
